// Some portions generated by Claude
import { useCallback, useRef, useState } from "react";
import { recorded, redone, undone, type HistoryStacks } from "./history-stack.ts";

/**
 * Undo and redo for the graph. `capture` takes a snapshot of the current state, `apply` puts one back. `push`,
 * `undo` and `redo` keep their identity, so components and listeners that use them are not recreated per change.
 */
export function useUndoHistory<T>(capture: () => T, apply: (snapshot: T) => void, limit: number) {
  const [stacks, setStacks] = useState<HistoryStacks<T>>({ past: [], future: [] });
  const stacksRef = useRef(stacks);
  stacksRef.current = stacks;
  const latest = useRef({ capture, apply });
  latest.current = { capture, apply };

  /** Records the state before a change (by default the state now). */
  const push = useCallback(
    (snapshot?: T) => {
      const before = snapshot ?? latest.current.capture();
      setStacks((current) => {
        const next = recorded(current, before, limit);
        stacksRef.current = next;
        return next;
      });
    },
    [limit],
  );
  const step = useCallback(
    (move: typeof undone) => {
      const result = move(stacksRef.current, latest.current.capture(), limit);
      if (!result) return false;
      stacksRef.current = result.stacks;
      setStacks(result.stacks);
      latest.current.apply(result.snapshot as T);
      return true;
    },
    [limit],
  );
  /** Goes back one change; false when there is none. */
  const undo = useCallback(() => step(undone), [step]);
  /** Goes forward one undone change; false when there is none. */
  const redo = useCallback(() => step(redone), [step]);
  return { push, undo, redo, canUndo: stacks.past.length > 0, canRedo: stacks.future.length > 0 };
}
